from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The color key is a horizontal strip repeated on several adjacent rows.
    key_rows = set()
    colors = None
    for y in range(h):
        end = y + 1
        while end < h and grid[end] == grid[y]:
            end += 1
        if end - y >= 2:
            seq = [v for v in grid[y] if v != 0]
            if len(seq) >= 2:
                key_rows.update(range(y, end))
                colors = seq
                break
    if colors is None:
        return [row[:] for row in grid]

    # Find a copy of the repeated figure outside the key.
    for color in colors:
        cells = {(r, c) for r in range(h) if r not in key_rows
                 for c in range(w) if grid[r][c] == color}
        if not cells:
            continue
        # Components are separate copies in the input; use one as the template.
        start = next(iter(cells))
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr in range(r-1, r+2):
                for nc in range(c-1, c+2):
                    if (nr, nc) != (r, c) and (nr, nc) in cells and (nr, nc) not in comp:
                        comp.add((nr,nc)); q.append((nr,nc))
        r0 = min(r for r,c in comp); r1 = max(r for r,c in comp)
        c0 = min(c for r,c in comp); c1 = max(c for r,c in comp)
        shape = {(r-r0,c-c0) for r,c in comp}
        block_h = r1-r0+1
        index = colors.index(color)
        top = r0 - index*block_h
        out = [[0]*w for _ in range(h)]
        for i, col in enumerate(colors):
            for dr, dc in shape:
                rr, cc = top + i*block_h + dr, c0 + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = col
        return out
    return [row[:] for row in grid]

